#!/usr/bin/env python3
"""Turn 35 Wave 51: CULT HEROES RESOLVED (the 92-vs-95 conflict), the STADIUM SECTOR LADDER (C-010),
and the DLL rank names below Veteran.

Wave 51 closes two of the longest-standing gaps in the corpus:

1. C-018 - CULT HEROES OVR (92 vs 95): the complete official 12-player collection is now known from
   two independent databases, and BOTH disputed numbers turn out to be correct readings of different
   things. The BASE card rating is 85 (max in the collection). The 92s are the LIVE-EVENT BOOSTED
   ratings (the App Store event copy says "Now available with boosted attributes"). The 95 is a
   FULLY MAXED card (85 + the +10 coach cap). Nothing is wrong; the sources were measuring three
   different states of the same card.

2. C-010 - STADIUM CAPACITY PER DIVISION: the full ladder is published - Academy 6,462 (starting) /
   Division 3 15,000 / Division 2 30,000 / Division 1 45,000 / Junior Elite 60,000 / Elite 80,000,
   with max seats 90,456, an Auto Build ceiling of 80,000, eight named sectors and three separate
   seat ladders (Ends 22 levels, Sides 29 levels, Corners 43 levels). The cheapest-seat rule falls
   straight out of the data: corners are the cheap seats, and the community's build order is now
   arithmetic rather than folklore.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w51')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-459: Cult Heroes ----------
e_ch=new_ev("dlsinside.com/players/specials/cult-heroes (DLS26 v13.430, code 160, updated 2026-09-16), dlsinside individual card pages for David Luiz (28325), David de Gea (28324) and Ander Herrera (28329), sakibpro.com/players/trending.php (15 Oct 2026) and sakibpro.com/dls-26-new-update-events-players (20 Aug 2026), dreamkitsapp.com/players/type/cult-heroes, r/DreamLeagueSoccer 1wele5q (17 Sep 2026), 1vtm4ty (21 Aug 2026), Apple App Store DLS26 version history + LIVE EVENT copy, official @dreamleaguesoccer.ftg TikTok, official Facebook page",
    "CULT HEROES RESOLVED - the complete 12-player collection, its ratings, and the end of the 92-vs-95 conflict. THE OFFICIAL COLLECTION (dlsinside, DLS26 v13.430, updated 2026-09-16, corroborated independently by sakibpro and dreamkitsapp): 12 players, obtained from CULT HERO AGENTS - David de Gea (GK, 85) - Pierre-Emerick Aubameyang (CF, 85) - Paulo Dybala (SS, 85) - Lorenzo Insigne (LW, 84) - Hakim Ziyech (RW, 84) - Francisco Alarcon (AM/CM, 84) - Nicolas Otamendi (CB, 84) - David Luiz (CB/DM, 84) - Daley Blind (CB/LB, 83) - Xherdan Shaqiri (AM, 83) - Ander Herrera (CM/DM, 83) - Vozinha (GK, 83; full name Josimar Jose Evora Dias, Cape Verde). Dorsal numbers per dlsinside: de Gea 1, Aubameyang 17, Dybala 10, Insigne 24, Ziyech 22, Alarcon 22, Otamendi 30, David Luiz 30, Vozinha 1, Blind 17, Shaqiri 23, Herrera 21. THREE AT 85, NINE AT 83-84, MAX RATING 85. HOW THE 92-vs-95 CONFLICT RESOLVES - all three numbers are correct readings of three different states of the same card: (a) 85 is the BASE card rating; (b) the 92s reported on r/DLS 1wele5q ('92 - Insigne, 92 - Aubameyang, 92 - Dybala, 92 - De Gea', 17 Sep 2026, the day after launch) are the LIVE-EVENT BOOSTED ratings - the App Store event copy for the collection reads 'LIVE EVENT Cult Heroes - Sign these top stars who are remembered by passionate football fans. NOW AVAILABLE WITH BOOSTED ATTRIBUTES'; (c) 95 is a FULLY MAXED card, since the coach cap is base + 10 (85 + 10 = 95). The KB's earlier note that Source A was 'showing post-boost/in-game OVR or an earlier build' is now confirmed precisely: post-boost during the event. ACQUISITION (official TikTok): 'Cult Heroes are coming to #DLS26 on September 16th. Find them by collecting Cult Hero Agents, available in Events, Drafts and the Season Pass.' sakibpro adds that three Season Passes are planned, each offering 2 Cult Heroes (one on the free tier, one on the premium tier) = 6 of the 12 obtainable through season passes alone; the rest come from Cult Hero Agents in Events and Drafts. A YouTube guide names three routes to Cult Hero Agents: Draft, Season Pass and events. r/DLS 1vtm4ty predicted the shape correctly a month early: '12 players, using special agent to get them, and 3 season pass with the same name. It's the same pattern like the dream star. The other thing is the highest stat is only 85, which is not strong enough to attract people paying' - so the community expected 82-84 with an 85 ceiling and got it. SAMPLE STATS (dlsinside): David Luiz 84 CB/DM - TAC 89, STR 85, CON 80, STA 82, SPE 78, SHO 67; David de Gea 85 GK - GKR 85, GKH 80, PAS 60, SPE 62; Ander Herrera 83 CM/DM - STA 91, PAS 86, CON 86, TAC 82, SPE 74. All three are SPECIAL cards, so they are exempt from the accommodation limit and sit outside squad size.",
    "evidence/raw/turn35_w51/EV-459_cult_heroes.html",
    "CULT HEROES RESOLVED (C-018): the complete official 12-player collection is David de Gea 85, Aubameyang 85, Dybala 85, Insigne 84, Ziyech 84, Alarcon 84, Otamendi 84, David Luiz 84, Blind 83, Shaqiri 83, Herrera 83, Vozinha 83 - max rating 85, from Cult Hero Agents in Events, Drafts and the Season Pass (3 passes x 2 heroes, one free + one premium = 6 of 12). THE 92-vs-95 CONFLICT RESOLVES AS THREE STATES OF ONE CARD: 85 = base; 92 = LIVE-EVENT BOOSTED rating (App Store: 'now available with boosted attributes'); 95 = fully maxed (85 + the +10 coach cap). Sample stats: Luiz TAC 89/STR 85, de Gea GKR 85/GKH 80, Herrera STA 91/PAS 86/CON 86",
    quality="community")

add_claim("THE COMPLETE CULT HEROES COLLECTION (12 players, DLS26 v13.430): David de Gea GK 85, Pierre-Emerick Aubameyang CF 85, Paulo Dybala SS 85, Lorenzo Insigne LW 84, Hakim Ziyech RW 84, Francisco Alarcon AM/CM 84, Nicolas Otamendi CB 84, David Luiz CB/DM 84, Daley Blind CB/LB 83, Xherdan Shaqiri AM 83, Ander Herrera CM/DM 83, Vozinha GK 83. Maximum rating in the collection is 85.", 2, "cards/cult-heroes-complete-list", [e_ch], notes="Two independent databases agree - resolves the official card list gap")
add_claim("C-018 RESOLVED: the 92-vs-95 Cult Heroes conflict is three states of the same card. 85 = the BASE rating; 92 = the LIVE-EVENT BOOSTED rating (the App Store event copy reads 'now available with boosted attributes', and the 92 reports are dated the day after the 16 Sep 2026 launch); 95 = a FULLY MAXED card (85 + the +10 coach cap). No source is wrong - they measured base, boosted and maxed respectively.", 2, "cards/c-018-resolved", [e_ch], notes="C-018 CLOSED")
add_claim("Cult Hero Agents are the acquisition route and are available in Events, Drafts and the Season Pass (official TikTok). Three Season Passes are planned, each offering 2 Cult Heroes - one on the free tier and one on the premium tier - so 6 of the 12 are obtainable through season passes alone.", 2, "cards/cult-heroes-acquisition", [e_ch])
add_claim("The community predicted the Cult Heroes shape correctly before launch: '12 players, using special agent to get them, and 3 season pass with the same name. It's the same pattern like the dream star. The other thing is the highest stat is only 85, which is not strong enough to attract people paying.'", 3, "cards/cult-heroes-prediction-confirmed", [e_ch])
add_claim("Sample Cult Heroes stats (dlsinside): David Luiz 84 CB/DM - TAC 89, STR 85, CON 80, STA 82, SPE 78, SHO 67; David de Gea 85 GK - GKR 85, GKH 80, PAS 60; Ander Herrera 83 CM/DM - STA 91, PAS 86, CON 86, TAC 82. As special cards they are exempt from the accommodation limit.", 2, "cards/cult-heroes-sample-stats", [e_ch])

# ---------- EV-460: Stadium ----------
e_st=new_ev("dlspedia.fandom.com/wiki/Dream_League_Soccer_Stadium (full sector seat and cost ladders, division seat requirements, sector names, pitch types), r/DreamLeagueSoccer lin626 (Feb 2021, Legendary minimum 85,000 + 51-coin bonus at 90,161), yg471t (Oct 2022, upgrade to 80,000 then customise freely), 176ntor (Oct 2023, 8 stands / 7 maxed / leave a corner), 13twf9y (May 2023, max each stand lowest-to-highest for the cheapest 92k), 18obd02 (Dec 2023, 5,625 gems + 10,000 coins for a completed stadium), 1h945fc (Dec 2024) and 15u4aeq (Aug 2023, downgrade removed), 1sw2dla (Apr 2026, lost stand variety), whgg7n (Aug 2022, one stand at a time is cheaper), dream-league-soccer.fandom.com Stadium + Division 3 pages, dlsinside.com/stadiums (255 real-club stadiums, v13.430)",
    "THE STADIUM LADDER - the capacity gate on promotion, the sector economics, and the cheapest build order. DIVISION SEAT REQUIREMENTS (dlspedia): Academy Division 6,462 (the starting capacity, 'already obtained when the game begin'), Division 3 15,000, Division 2 30,000, Division 1 45,000, Junior Elite 60,000, ELITE DIVISION 80,000. THE PROMOTION RULE IS EXPLICIT: 'If you finish your championship and automatically you are promoted to next division. But if you haven't a precise number (per each league) of seats you will not be promoted to next division' - capacity is a hard gate on promotion, not a bonus. STRUCTURE: eight sectors (two Ends, two Sides, four Corners) named North Stand, North East Stand, East Stand, South East Stand, South Stand, South West Stand, West Stand and North West Stand; seven pitch patterns (horizontal stripe, vertical stripe, check, diagonal A, diagonal B, diamond, circles); the stadium is renameable ('Dream F.C. Stadium' by default); an 'Auto Build Capacity' button takes a target seat number and shapes the stadium automatically. CAPACITY LIMITS: minimum 6,462, maximum 90,456 seats, with the Auto Build ceiling at 80,000. THE THREE SEAT LADDERS (each sector is upgraded independently, level by level): ENDS 22 levels from 1,323 to 9,722 (End 1-2: 1,323; End 5: 3,344; End 11: 4,786; End 22: 9,722) - SIDES 29 levels from 1,908 to 14,128 (Side 5: 5,125; Side 10: 6,882; Side 15: 8,113; Side 24: 12,286; Side 29: 14,128) - CORNERS 43 levels from 0 to 10,692, and the corners are where the cheap seats are: Corner 7 costs about 100 coins for 722 seats, Corner 9 adds 427 for ~90, Corner 11 adds 1,264 for ~130, and the corner ladder reaches 10,692 by level 43 while the End ladder only reaches 9,722 by level 22. SECTOR COSTS run from 0 coins for the first level to roughly 300 coins at the top of the corner ladder and 650 for the last End level - all in COINS, not gems, which is why the stadium is a coin project and the facilities are a gem project. THE COMMUNITY BUILD ORDER IS NOW ARITHMETIC: 'Never upgrade the same stand twice. Save up until you can upgrade whatever stand you want to upgrade at once' - 'there are 8 stands, you'll need to upgrade 7 to the max to get 85,000 capacity. The last stand un-upgraded must be a corner stand, unless it won't be 85,000' - 'upgrade one stand max every time you want to upgrade stadium it's cheaper' - and the cheapest route to a full 92k is 'I completely maxed out each part of the stadium individually from the lowest capacity stand to the highest one'. A COMPLETED STADIUM cost one player 5,625 gems and 10,000 coins. DOWNGRADING HAS BEEN REMOVED: in DLS16-DLS23 you could drop below a division requirement (one player downgraded from 85,000 to 35,000 to enter Legendary, another to 20,000), but since roughly DLS24 'they removed downgrade option or option to make changes to the stadium if you don't have required capacity' - so capacity, once built, is effectively permanent, and multiple players complain the change killed ground variety. ONE CONFLICT: an older fandom wiki puts Division 3 at 35,000 and Division 2 at 45,000, which is an earlier build's ladder and is superseded by the dlspedia table; a 2021 thread independently cites 85,000 for the top division, which brackets the current 80,000 (the figure moved between builds).",
    "evidence/raw/turn35_w51/EV-460_stadium_ladder.html",
    "STADIUM LADDER RESOLVED (C-010): division seat gates are Academy 6,462 (starting) / Div 3 15,000 / Div 2 30,000 / Div 1 45,000 / Junior Elite 60,000 / Elite 80,000, and capacity is a HARD PROMOTION GATE ('if you haven't a precise number of seats you will not be promoted'). Max capacity 90,456 with an Auto Build ceiling of 80,000; 8 named sectors (2 Ends, 2 Sides, 4 Corners); 7 pitch patterns. Three independent seat ladders: Ends 22 levels to 9,722, Sides 29 levels to 14,128, Corners 43 levels to 10,692 - CORNERS ARE THE CHEAP SEATS (Corner 7: 722 seats for about 100 coins). Sector costs run 0 to about 650 COINS per level, so the stadium is a coin project. Cheapest build order: max one stand at a time, never the same stand twice, leave one corner un-upgraded, and max each stand from the lowest to the highest. Downgrading was removed around DLS24, so capacity is permanent. A completed stadium cost 5,625 gems + 10,000 coins",
    quality="community")

add_claim("THE DIVISION SEAT LADDER: Academy Division 6,462 (the starting capacity), Division 3 15,000, Division 2 30,000, Division 1 45,000, Junior Elite 60,000, Elite Division 80,000. Maximum stadium capacity is 90,456 seats with an Auto Build ceiling of 80,000.", 2, "stadium/division-seat-ladder", [e_st], notes="C-010 substantially resolved - one older wiki gives a superseded 35,000/45,000 ladder")
add_claim("STADIUM CAPACITY IS A HARD PROMOTION GATE, not a bonus: 'if you finish your championship and automatically you are promoted to next division. But if you haven't a precise number (per each league) of seats you will not be promoted to next division.'", 2, "stadium/capacity-promotion-gate", [e_st])
add_claim("The stadium has 8 sectors - two Ends, two Sides and four Corners - named North, North East, East, South East, South, South West, West and North West Stands, and 7 pitch patterns (horizontal stripe, vertical stripe, check, diagonal A, diagonal B, diamond, circles). An 'Auto Build Capacity' button takes a target seat number and shapes the stadium automatically.", 2, "stadium/sectors-and-pitches", [e_st])
add_claim("THE THREE SEAT LADDERS: Ends run 22 levels from 1,323 to 9,722 seats; Sides run 29 levels from 1,908 to 14,128; Corners run 43 levels from 0 to 10,692. CORNERS ARE THE CHEAP SEATS - Corner 7 costs about 100 coins for 722 seats and Corner 11 adds 1,264 for about 130 - so corner stands deliver the most seats per coin.", 2, "stadium/sector-seat-ladders", [e_st], notes="The corner-first build order is now arithmetic, not folklore")
add_claim("Sector upgrade costs run from 0 coins for the first level to roughly 300 coins at the top of the corner ladder and about 650 for the final End level - all in COINS, not gems. The stadium is therefore a COIN project while the facilities are a GEM project.", 2, "stadium/sector-costs-in-coins", [e_st])
add_claim("THE CHEAPEST STADIUM BUILD ORDER (community, now backed by the ladders): never upgrade the same stand twice; save up and upgrade one stand at a time; max each stand from the lowest capacity to the highest; leave one CORNER stand un-upgraded, because 7 maxed stands reach the top-division requirement while 8 do not fit it. A fully completed stadium cost one player 5,625 gems and 10,000 coins.", 3, "stadium/cheapest-build-order", [e_st])
add_claim("STADIUM DOWNGRADING HAS BEEN REMOVED: in DLS16-DLS23 players could drop capacity below a division requirement (one downgraded from 85,000 to 35,000 to enter Legendary, another to 20,000 for realism), but since roughly DLS24 'they removed downgrade option or option to make changes to the stadium if you don't have required capacity'. Capacity, once built, is effectively permanent.", 3, "stadium/downgrade-removed", [e_st], notes="Consequential: build to the division gate, not to a dream design, because you cannot undo it")
add_claim("STADIUM CAPACITY CONFLICT: an older fandom wiki lists Division 3 at 35,000 and Division 2 at 45,000, and a 2021 thread cites 85,000 for the top division - both are earlier builds. The current dlspedia ladder (15,000 / 30,000 / 45,000 / 60,000 / 80,000) is adopted, with the note that the top-division figure has moved between 80,000 and 85,000 across builds.", 3, "stadium/capacity-ladder-conflict", [e_st], notes="Verify the exact current gate in-client before committing the last stand")

